{"policy":"permit (
    principal is Instructor,
    action == Action::"viewStudentRecord",
    resource is StudentRecord
);

permit (
    principal is Registrar,
    action == Action::"viewStudentRecord",
    resource is StudentRecord
)
when {
    resource.status == "withdrawn" &&
    resource.ferpaDirectoryInformationBlock
};

forbid (
    principal,
    action == Action::"viewStudentRecord",
    resource is StudentRecord
)
when {
    (principal is Instructor || principal is Student || principal is Parent) &&
    resource.status == "withdrawn" &&
    resource.ferpaDirectoryInformationBlock
};"}
